pid, ticks = value['pid'], value['startTimeTicks']
if type(pid) is not int or pid <= 1 or type(ticks) is not int or ticks < 0:
    raise ValueError('invalid cooperative marker identity')
while identity(pid) == ticks:
    time.sleep(0.01)

